Given an array arr[], find the largest divisible subset in the given array. If there are multiple subsets of the largest size, return the lexicographically greatest one after sorting in ascending order.Note: A subset is called divisible if for every pair (x, y) in the subset, either x divides y or y divides x.Examples:Input: arr[]  = [1, 16, 7, 8, 4]Output: [1, 4, 8, 16]Explanation: In the output subset, for every pair either the first element divides second or second divides first.Input : arr[] = [2, 4, 3, 8]Output : [2, 4,  8]Explanation: In the output subset, for every pair either the first element divides second or second divides first.Try It YourselfTable of Content[Naive Approach] Generate all subset of array - O(2^n*n^2) Time and O(n) Space[Better Approach] Using Recursion - O(2^n*n) Time and O(n) Space[Expected Approach 1] Using Top-Down DP(Memoization) - O(n^2) Time and O(n) Space[Expected Approach 2] Using Bottom-Up DP (Tabulation) – O(n^2) Time and O(n) Space[Naive Approach] Generate all subset of array - O(2^n*n^2) Time and O(n) SpaceA simple solution is to generate all subsets of a given set. For each subset, we check if all pairs of elements satisfy the divisibility condition (a % b == 0 || b % a == 0). Among all valid subsets, we track the one with the largest size, and in case of ties, we pick the lexicographically greatest one. This approach is simple but inefficient due to exponential time complexity.
            C++

    #include <iostream>
#include <vector>
#include <algorithm>
using namespace std;


vector<int> res;

// Function to check if every pair in the subset
// satisfies the divisibility condition
bool isValid(const vector<int>& subset) {

    for (int i = 0; i < subset.size(); ++i) {
        for (int j = i + 1; j < subset.size(); ++j) {

            // If neither element divides the other, it's not a valid subset
            if (subset[i] % subset[j] != 0 && subset[j] % subset[i] != 0)
                return false;
        }
    }
    return true;
}

// Lexicographical comparison
int compareLex(const vector<int>& a, const vector<int>& b) {
    for (int i = 0; i < a.size(); ++i) {
        if (a[i] != b[i])
            return a[i] > b[i] ? 1 : -1;
    }
    return 0;
}

// Recursive DFS function to generate all subsets and track the best one
void dfs(const vector<int>& arr, vector<int>& curr, int index) {

    // Base case: if we've considered all elements
    if (index >= arr.size()) {
        if (isValid(curr)) {
            // If current subset is longer than the best so far, update it
            if (curr.size() > res.size()) {
                res = curr;
            } 
            // If size is the same, update only if lexicographically greater
            else if (curr.size() == res.size() && compareLex(curr, res) > 0){
                res = curr;
            }
        }
        return;
    }

    // Include the current element in the subset
    curr.push_back(arr[index]);
    dfs(arr, curr, index + 1);

    // Backtrack: remove the element and explore without it
    curr.pop_back();
    dfs(arr, curr, index + 1);
}

// Wrapper function to find the largest divisible subset
vector<int> largestSubset(vector<int>& arr) {

    // Sort the array to simplify lexicographical comparisons
    sort(arr.begin(), arr.end());

    // Temporary subset to build during DFS
    vector<int> curr; 
    // Clear previous results
    res.clear();       
    // Start DFS from index 0
    dfs(arr, curr, 0);  
    return res;
}

int main() {
    vector<int> arr = {1, 16, 7, 8, 4};  
    vector<int> result = largestSubset(arr); 

    // Print the result
    for (int num : result) cout << num << " ";
    return 0;
}


