    public static void main(String[] args) {

        GfG sol = new GfG();
        int[] arr = {1, 16, 7, 8, 4};
        ArrayList<Integer> result = sol.largestSubset(arr);

        // Output the largest divisible subset
        for (int num : result) {
           System.out.print(num + " ");
        }
    }
}


